$:set -euo pipefail
if test -f README.md; then cat README.md >/dev/null; fi
cat AGENTS.md >/dev/null
gh api repos/BestNameYet/Terminals/issues/3 --jq .body >/dev/null
gh auth setup-git
git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
node <<'NODE'

"use strict";
const fs=require("fs"),assert=require("assert"),crypto=require("crypto");
const pathOriginal="Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-draft.json";
const pathEncoded="Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-aliased-copy.json";
const pathReference="references/instruction-wrapper-key-aliases.json";
const pathSourceRule="Tasks/TasksCompleted/user-prompt-task-1794193968-rule.json";
const pathTask="Tasks/User Prompt Task Queue/user-prompt-task-1794193447.json";
const read=p=>JSON.parse(fs.readFileSync(p,"utf8"));
const write=(p,obj,compact=false)=>fs.writeFileSync(p,JSON.stringify(obj,...(compact?[null,0]:[null,2]))+"\n","utf8");
const prior=read(pathOriginal),oldEncoded=read(pathEncoded),ref=read(pathReference),source=read(pathSourceRule),task=read(pathTask);
assert(Array.isArray(prior)&&prior.length===3&&Array.isArray(prior[2])&&prior[2].length===2);
assert(Array.isArray(source)&&source.length===3&&source[1]&&typeof source[1]==="object");
assert.strictEqual(task.status,"pending_revision");
assert.strictEqual(oldEncoded[0].alias_lookup_path,pathReference);
const analyticsName="End-of-Turn Conversation Analytics Recording";
assert.strictEqual(prior[2][0].title,"Conversation Analytics");
assert.strictEqual(prior[2][1].title,analyticsName);
const oldRule={...prior[2][1]};
delete oldRule.title;
assert.deepStrictEqual(oldRule,source[1],"Original analytics rule body must match source exactly");
const next=structuredClone(prior);
next[2]={title:analyticsName,...structuredClone(source[1])};
assert(!Array.isArray(next[2])&&typeof next[2]==="object");
assert.deepStrictEqual(next[2],prior[2][1],"No change beyond removal of redundant group wrapper");
const seen=new Map();
function visit(node){
 if(Array.isArray(node)){node.forEach(visit);return;}
 if(node===null||typeof node!=="object")return;
 for(const [k,v] of Object.entries(node)){seen.set(k,(seen.get(k)||0)+1);visit(v);}
}
visit(next);
const kept=Object.entries(ref.alias_to_key).filter(([alias,key])=>seen.has(key));
const aliases=Object.fromEntries(kept);
assert(Object.keys(aliases).length===seen.size,"Alias table does not cover revised draft");
assert(new Set(Object.values(aliases)).size===Object.keys(aliases).length);
const keyAliases=new Map(Object.entries(aliases).map(([alias,key])=>[key,alias]));
function encode(node) {
 if(Array.isArray(node))return node.map(encode);
 if(node===null||typeof node!=="object")return node;
 const out={};
 for(const [k,v] of Object.entries(node)){const a=keyAliases.get(k);assert(a,"No alias: "+k);out[a]=encode(v);}
 return out;
}
function decode(node){
 if(Array.isArray(node))return node.map(decode);
 if(node===null||typeof node!=="object")return node;
 const out={};
 for(const [k,v] of Object.entries(node)){const originalKey=k==="alias_lookup_path"?k:aliases[k];assert(originalKey,"Unknown alias: "+k);out[originalKey]=decode(v);}
 return out;
}
const encoded=encode(next);
encoded[0].alias_lookup_path=pathReference;
const reconstructed=decode(encoded);
delete reconstructed[0].alias_lookup_path;
assert.deepStrictEqual(reconstructed,next);
assert.deepStrictEqual(next[0],prior[0]);
assert.deepStrictEqual(next[1],prior[1]);
ref.alias_to_key=aliases;
ref.original_key_count=seen.size;
ref.total_key_count_including_lookup=seen.size;
ref.aliases_with_one_character=Object.keys(aliases).filter(x=>x.length===1).length;
ref.aliases_with_two_characters=Object.keys(aliases).filter(x=>x.length===2).length;
ref.source_template_sha256=crypto.createHash("sha256").update(JSON.stringify(next,null,2)+"\n").digest("hex");
task.task.deliverable="Two external rule references with examples, plus an instruction-wrapper draft containing the complete accepted scope rule and the complete conversation-analytics rule as separate standalone objects.";
task.task.acceptance_criteria=task.task.acceptance_criteria.map(x=>x==="The analytics rule body is semantically intact and not represented as operationally activated."?x:x);
task.task.amendments.push({
 purpose:"Make Conversation Analytics one standalone rule object because the former two-element grouped-rule array added only redundant context.",
 user_instruction_summary:"Conversation analytics should be an object, not an array. Its former group-explainer at index 0 and the subordinate rule at index 1 were redundant; retain one complete analytics rule object without the superfluous group explainer.",
 implementation:"Replace outer index 2 with the preexisting complete titled analytics rule object, preserving its original rule body byte-for-byte at the parsed JSON value level. Update the editable aliased copy and its exact-key alias lookup without modifying the separate accepted analytics source."
});
write(pathOriginal,next);
write(pathEncoded,encoded,true);
write(pathReference,ref);
write(pathTask,task);
const roundtrip=decode(read(pathEncoded));
delete roundtrip[0].alias_lookup_path;
assert.deepStrictEqual(roundtrip,read(pathOriginal));
assert.deepStrictEqual(read(pathOriginal)[2],{title:analyticsName,...source[1]});
assert.strictEqual(read(pathTask).status,"pending_revision");
console.log("UPDATED_ORIGINAL",pathOriginal);
console.log("UPDATED_ALIASED",pathEncoded);
console.log("UPDATED_REFERENCE",pathReference);
console.log("UPDATED_TASK",pathTask);
console.log("OUTER_ENTRIES",next.length);
console.log("ANALYTICS_TYPE",typeof next[2],"IS_ARRAY",Array.isArray(next[2]));
console.log("ANALYTICS_BODY_IDENTICAL",true);
console.log("SCOPE_UNCHANGED",true);
console.log("ALIAS_ROUNDTRIP",true);
console.log("KEY_ALIASES",seen.size,"REMOVED_UNUSED_ALIASES",Object.keys(ref.alias_to_key).length===seen.size);
console.log("DRAFT_CHARACTERS",JSON.stringify(next,null,2).length+1);
console.log("ALIAS_COPY_CHARACTERS",JSON.stringify(encoded).length+1);

NODE
git add -- 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-draft.json' 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-aliased-copy.json' 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447.json' 'references/instruction-wrapper-key-aliases.json'
git diff --cached --check
git commit -m 'Represent conversation analytics as one complete standalone instruction rule'
for i in 1 2 3 4; do git fetch origin main -q; git rebase origin/main -q; if git push origin HEAD:main; then break; fi; test "$i" -lt 4; done
printf 'PUBLISHED_COMMIT '; git rev-parse HEAD
git show --stat --oneline HEAD
